using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UI;
namespace IdleIntelligence.Runtime {
 // Explicit development-player verification only. Never selects a normal user's save.
 public sealed class PlayerSmoke:MonoBehaviour {
  static string output;static string dir;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Configure(){var args=Environment.GetCommandLineArgs();if(!Debug.isDebugBuild||!args.Contains("-idle-smoke"))return;int index=Array.IndexOf(args,"-idle-smoke-dir");if(index<0||index+1>=args.Length)throw new InvalidOperationException("Smoke directory required");dir=Path.GetFullPath(args[index+1]);string temp=Path.GetFullPath(Path.GetTempPath());if(!dir.StartsWith(temp,StringComparison.Ordinal)||Directory.Exists(dir))throw new InvalidOperationException("Smoke requires a new directory below the system temp directory");Directory.CreateDirectory(dir);output=Path.Combine(dir,"player-smoke.json");GameRuntime.SavePathOverride=Path.Combine(dir,"isolated-save.json");var root=new GameObject("LocalPlayerSmoke");DontDestroyOnLoad(root);root.AddComponent<PlayerSmoke>();}
  void Click(string name){var button=GameObject.Find(name)?.GetComponent<Button>();if(button==null||!button.interactable)throw new Exception("Unavailable actual action "+name);button.onClick.Invoke();}
  IEnumerator Start(){Screen.SetResolution(390,844,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(1);Exception error=null;try{var game=FindFirstObjectByType<GameRuntime>();if(!game.Writable||game.State.Credits.CompareTo(ScientificNumber.From(50))!=0)throw new Exception("Fresh save mismatch");game.Show("story");GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";Click("StoryChooseName");for(int i=0;i<5;i++)Click("StoryContinue");game.NavigateTo("hardware","TapLab");Click("TapLab");Click("hardware-calculator");game.Show("training");Click("training-quality");if(game.State.Training==null||!game.State.Journal.Has("training-start"))throw new Exception("Real tutorial transaction not durable");}catch(Exception e){error=e;}
   if(error==null){yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;try{var game=FindFirstObjectByType<GameRuntime>();if(game.State.Retention.aiName!="AURA"||!game.State.Journal.Has("training-start")||game.State.Hardware[0]!=1)throw new Exception("Actual player reload mismatch");game.Show("story");}catch(Exception e){error=e;}}
   yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(dir,"player-portrait.png"));yield return new WaitForSecondsRealtime(.5f);File.WriteAllText(output,JsonUtility.ToJson(new Report{passed=error==null,error=error?.ToString()??"",unity=Application.unityVersion,platform=Application.platform.ToString(),os=SystemInfo.operatingSystem,graphics=SystemInfo.graphicsDeviceName,width=Screen.width,height=Screen.height,savePath=GameRuntime.SavePathOverride},true));Application.Quit(error==null?0:1);
  }
  [Serializable]sealed class Report{public bool passed;public string error,unity,platform,os,graphics,savePath;public int width,height;}
 }
}
